def _init_promises_today():
    """بنحدد تاريخ اليوم مرة واحدة في أول رن للصفحة لـ ميترفرش مع كل إعادة تشغيل."""
    if TODAY_KEY not in st.session_state:
        st.session_state[TODAY_KEY] = datetime.now().date()


def parse_date_cell(val):
    """بيحول خلية التاريخ لـ date مهما كان شكلها (datetime / date / نص)."""
    if pd.isna(val):
        return None
    if isinstance(val, datetime):
        return val.date()
    if isinstance(val, pd.Timestamp):
        return val.date()
    if hasattr(val, "date"):
        return val.date()
    txt = str(val).strip()
    if not txt:
        return None
    for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%m/%d/%Y", "%Y/%m/%d", "%d-%m-%Y", "%d %B %Y"):
        try:
            return datetime.strptime(txt, fmt).date()
        except (ValueError, TypeError):
            continue
    try:
        return pd.to_datetime(txt, errors="coerce").date()
    except Exception:
        return None




def render_promises_dashboard(df, sales_col, net_col, title_suffix):
    """عرض ملخص الوعود باستخدام مكونات Streamlit الأصلية ورسوم Plotly فقط."""
    st.subheader(f"📊 ملخص أداء الوعود — {title_suffix}")
    total_promises = len(df)
    total_amount = pd.to_numeric(df[net_col], errors="coerce").sum() if net_col else 0
    unique_agents = int(df[sales_col].nunique()) if sales_col else 0
    avg_amount = total_amount / total_promises if total_promises else 0
    m1, m2, m3, m4 = st.columns(4)
    m1.metric("🤝 إجمالي الوعود", f"{total_promises:,}")
    m2.metric("💰 إجمالي المبالغ", f"{total_amount:,.0f}")
    m3.metric("👤 عدد المحصّلين", f"{unique_agents:,}")
    m4.metric("📈 متوسط الوعد", f"{avg_amount:,.0f}")

    if total_promises and sales_col:
        c1, c2 = st.columns(2)
        agent_counts = df[sales_col].value_counts().head(10).sort_values().reset_index()
        agent_counts.columns = ["المحصّل", "عدد الوعود"]
        with c1:
            fig = px.bar(
                agent_counts, x="عدد الوعود", y="المحصّل", orientation="h",
                title="🔝 أعلى 10 محصّلين من حيث عدد الوعود",
                color="عدد الوعود", color_continuous_scale=[THEME["surface_2"], COLOR_ACCENT],
                template=PLOTLY_TEMPLATE,
            )
            fig.update_layout(**PLOTLY_LAYOUT, height=400, yaxis_title="")
            st.plotly_chart(fig, use_container_width=True, config=PLOTLY_CONFIG)
        if net_col:
            with c2:
                amounts = df.groupby(sales_col)[net_col].sum().sort_values(ascending=False).head(8).reset_index()
                amounts.columns = ["المحصّل", "إجمالي المبالغ"]
                fig = px.pie(
                    amounts, values="إجمالي المبالغ", names="المحصّل", hole=0.5,
                    title="🍩 توزيع المبالغ على المحصّلين",
                    template=PLOTLY_TEMPLATE,
                    color_discrete_sequence=[COLOR_ACCENT, COLOR_SUCCESS, COLOR_WARN, COLOR_FAIL, "#3B82F6", "#8B5CF6"],
                )
                fig.update_layout(**PLOTLY_LAYOUT, height=400)
                st.plotly_chart(fig, use_container_width=True, config=PLOTLY_CONFIG)




def _show_promises_results(df, target_date, summary, filename=None, from_cache=False):
    total_in_file = summary.get("total_in_file", len(df))
    st.info(
        f"📌 الوعود القائمة بتاريخ {target_date:%Y-%m-%d}: {len(df):,} وعد من {max(total_in_file, 0):,} صف. "
        f"تم استبعاد {summary.get('dropped_sales', 0)} مُحصّل، و{summary.get('dropped_sub', 0)} حالة، و{summary.get('dropped_due', 0)} تاريخ."
    )
    if len(df) == 0:
        st.warning("لا توجد وعود قائمة لهذا التاريخ بعد تطبيق الفلاتر.")
        return
    sales_col = summary.get("sales_col")
    substate_col = summary.get("substate_col")
    duedate_col = summary.get("duedate_col")
    net_col = summary.get("net_col")
    cols_used = [n for n, c in [("المحصّل", sales_col), ("الحالة الفرعية", substate_col), ("تاريخ المتابعة", duedate_col), ("صافي المبلغ", net_col)] if c]
    st.caption("الأعمدة المعتمدة: " + " · ".join(cols_used))
    render_promises_dashboard(df, sales_col, net_col, "اليوم")
    st.subheader(f"👀 لمحة من بيانات الوعود — أول {min(15, len(df))} وعد")
    preview_cols = [c for c in [sales_col, substate_col, duedate_col, net_col] if c]
    st.dataframe(df[preview_cols].head(15), use_container_width=True, hide_index=True)
    st.subheader(f"📊 ملخص الوعود لكل محصّل — {target_date:%Y-%m-%d}")
    if summary.get("summary_df") is not None:
        st.dataframe(summary["summary_df"], use_container_width=True, hide_index=True)
    st.subheader("📋 جدول الوعود القائمة التفصيلي")
    st.dataframe(df[preview_cols], use_container_width=True, hide_index=True)
    out_excel = io.BytesIO()
    with pd.ExcelWriter(out_excel, engine="openpyxl") as writer:
        df.to_excel(writer, index=False, sheet_name="الوعود القائمة")
    st.download_button(
        "⬇️ تحميل تقرير الوعود (Excel)", data=out_excel.getvalue(),
        file_name=f"تقرير_الوعود_{target_date:%Y-%m-%d}.xlsx",
        mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        use_container_width=True, key="promises_excel_download_single", type="primary",
    )



PROMISES_RESULT_KEY = "promises_result"  # كاش نتائج الوعود القائمة (فلتر: اليوم)
BROKEN_RESULT_KEY = "promises_broken_result"  # كاش نتائج الوعود المكسورة (فلتر: قبل اليوم)


def _run_promises_pipeline(
    uploaded,
    result_key,
    due_mode,
    count_label,
):
    """معالجة ملف المحفظة (فلترة + تجميع) وحفظ النتيجة في كاش الصفحة.

    - ``due_mode='today'``: Follow up Due Date == تاريخ اليوم (وعود قائمة).
    - ``due_mode='before'``: Follow up Due Date < تاريخ اليوم (وعود مكسورة).
    - ``count_label``: نص ملصق التجميع (مثلًا \"الوعود القائمة\" أو \"الوعود المكسورة\").

    بترجع ``True`` لو تم الحفظ في الكاش، و``False`` لو اتعرضت من الكاش مباشرة.
    """
    _file_hash = hashlib.sha256(uploaded.getvalue()).hexdigest()
    cached = st.session_state.get(result_key)
    if cached and cached.get("file_hash") == _file_hash:
        return False  # النتيجة موجودة في الكاش من رفع الملف ده — مش يلزم وجود إعادة معالجة

    try:
        raw_df = read_uploaded_dataframe(uploaded)
    except Exception as e:
        st.error(f"تعذر قراءة الملف: {e}")
        return False

    total_in_file = len(raw_df) - 1  # قبل حذف أول صف
    df = raw_df

    # 1) حذف أول صف بعد العناوين (زي قاعدة باقي الملفات في التطبيق)
    if len(df) > 0:
        df = df.iloc[1:].reset_index(drop=True)

    sales_col = find_column(df, SALES_PERSON_CANDIDATES)
    substate_col = find_column(df, PROMISE_SUB_STATE_CANDIDATES)
    duedate_col = find_column(df, PROMISE_DUE_DATE_CANDIDATES)
    net_col = find_column(df, PROMISE_NET_AMOUNT_CANDIDATES)

    missing = [n for n, c in [
        ("المحصّل (Salesperson)", sales_col),
        ("الحالة الفرعية (Sub State)", substate_col),
        ("تاريخ المتابعة (Follow up Due Date)", duedate_col),
    ] if not c]
    if missing:
        st.error(
            "تعذر العثور على أعمدة مهمة في الملف. الأعمدة المطلوبة: "
            f"{', '.join(missing)}\n\nالأعمدة الموجودة في الملف: {', '.join(df.columns.astype(str))}"
        )
        return False

    # 2) فلترة Salesperson — نستبعد المحصّلين المحددين
    sales_vals = df[sales_col].astype(str).str.strip()
    keep_sales = ~sales_vals.isin(PROMISE_EXCLUDED_SALES)
    dropped_sales = int((~keep_sales).sum())
    df = df[keep_sales].copy()

    # 3) فلترة Sub State = واعد بالسداد
    if substate_col:
        sub_vals = df[substate_col].astype(str).str.strip()
        keep_sub = sub_vals == PROMISE_SUB_STATE_VALUE
        dropped_sub = int((~keep_sub).sum())
        df = df[keep_sub].copy()
    else:
        dropped_sub = 0

    # 4) فلترة Follow up Due Date حسب وضع التبويبة
    target_date = st.session_state[TODAY_KEY]
    due_vals = pd.Series([parse_date_cell(v) for v in df[duedate_col]], index=df.index)
    if due_mode == "before":
        keep_due = due_vals.apply(lambda d: d is not None and d < target_date)
        due_desc = f"التاريخ قبل اليوم (< {target_date.strftime('%Y-%m-%d')})"
    else:
        keep_due = due_vals == target_date
        due_desc = f"التاريخ يساوي اليوم ({target_date.strftime('%Y-%m-%d')})"
    dropped_due = int((~keep_due).sum())
    df = df[keep_due].copy()

    # 5) الجدول التجميعي لكل محصّل
    if net_col and net_col in df.columns:
        summary_df = df.groupby(sales_col).agg(
            **{
                count_label: (duedate_col, "count"),
                "صافي المديونية (Net Amount)": (net_col, "sum"),
            }
        )
    else:
        summary_df = df.groupby(sales_col).agg(
            **{count_label: (duedate_col, "count")}
        )
    summary_df = summary_df.sort_values(count_label, ascending=False).reset_index()
    summary_df.columns = ["المحصّل " + str(sales_col), count_label] + (
        ["صافي المديونية (Net Amount)"] if net_col and net_col in df.columns else []
    )

    # 💾 حفظ النتائج في الكاش — تفضل موجودة لحد ما نعمل reload أو نشيل الملف
    st.session_state[result_key] = {
        "df": df,
        "summary_df": summary_df,
        "target_date": target_date,
        "filename": uploaded.name,
        "file_hash": _file_hash,
        "sales_col": sales_col,
        "substate_col": substate_col,
        "duedate_col": duedate_col,
        "net_col": net_col,
        "total_in_file": total_in_file,
        "dropped_sales": dropped_sales,
        "dropped_sub": dropped_sub,
        "dropped_due": dropped_due,
        "due_mode": due_mode,
        "due_desc": due_desc,
    }
    return True


def _render_cached_promises_page(result_key, placeholder_text):
    """عرض صفحة وعود من الكاش — سواء اتعملت دلوقتي أو محفوظة من رفع سابق قبل شيل الملف."""
    cached = st.session_state.get(result_key)
    if cached:
        if cached.get("due_mode") == "before":
            _show_broken_results(
                cached["df"],
                cached["target_date"],
                cached,
                filename=cached.get("filename"),
            )
        else:
            _show_promises_results(
                cached["df"],
                cached["target_date"],
                cached,
                filename=cached.get("filename"),
            )
    else:
        st.info(f"📂 ارفع ملف المحفظة (Excel أو CSV) لعرض النتائج — ستظل النتائج محفوظة حتى إعادة تحميل الصفحة. {placeholder_text}")


def page_standing_promises():
    """تويب الوعود القائمة: رفع المحفظة → فلترة → جدول الوعود + تنزيل + تجميع بالمحصّل."""
    _init_promises_today()

    page_header(
        "STANDING PROMISES",
        "📗 الوعود القائمة",
        "ارفع ملف المحفظة (Excel) لعرض الوعود المستحقة اليوم فقط، مع ملخص لكل محصّل وصافي المديونية",
    )

    uploaded = st.file_uploader(
        "📂 ارفع ملف المحفظة (Excel أو CSV)",
        type=["xlsx", "xls", "csv"],
        key="promises_portfolio_upload",
    )

    if uploaded is not None:
        st.caption(f"الملف المختار: {uploaded.name}")
        processed = _run_promises_pipeline(
            uploaded, PROMISES_RESULT_KEY, due_mode="today", count_label="عدد الوعود القائمة"
        )
        if not processed:
            # النتيجة جاية من الكاش — نعرضها مباشرة من غير إعادة معالجة
            cached = st.session_state[PROMISES_RESULT_KEY]
            _show_promises_results(
                cached["df"],
                cached["target_date"],
                cached,
                filename=cached.get("filename"),
            )
            return

    _render_cached_promises_page(PROMISES_RESULT_KEY, "")


def page_broken_promises():
    """تويب الوعود المكسورة: نفس منطق القائمة بس فلتر تاريخ المتابعة = قبل تاريخ اليوم."""
    _init_promises_today()

    page_header(
        "BROKEN PROMISES",
        "📕 الوعود المكسورة",
        "ارفع ملف المحفظة (Excel) لعرض الوعود التي تجاوزت تاريخ متابعتها وأصبحت مكسورة، مع ملخص لكل محصّل وصافي المديونية",
    )

    uploaded = st.file_uploader(
        "📂 ارفع ملف المحفظة (Excel أو CSV)",
        type=["xlsx", "xls", "csv"],
        key="broken_portfolio_upload",
    )

    if uploaded is not None:
        st.caption(f"الملف المختار: {uploaded.name}")
        processed = _run_promises_pipeline(
            uploaded, BROKEN_RESULT_KEY, due_mode="before", count_label="عدد الوعود المكسورة"
        )
        if not processed:
            cached = st.session_state[BROKEN_RESULT_KEY]
            _show_broken_results(
                cached["df"],
                cached["target_date"],
                cached,
                filename=cached.get("filename"),
            )
            return

    _render_cached_promises_page(BROKEN_RESULT_KEY, "")


def _show_broken_results(df, target_date, summary, filename=None):
    total_in_file = summary.get("total_in_file", len(df))
    st.info(
        f"📌 الوعود المكسورة قبل {target_date:%Y-%m-%d}: {len(df):,} وعد من {max(total_in_file, 0):,} صف. "
        f"تم استبعاد {summary.get('dropped_sales', 0)} مُحصّل، و{summary.get('dropped_sub', 0)} حالة، و{summary.get('dropped_due', 0)} تاريخ."
    )
    if len(df) == 0:
        st.warning("لا توجد وعود مكسورة بعد تطبيق الفلاتر.")
        return
    sales_col = summary.get("sales_col")
    substate_col = summary.get("substate_col")
    duedate_col = summary.get("duedate_col")
    net_col = summary.get("net_col")
    display_cols = [c for c in [sales_col, substate_col, duedate_col, net_col] if c]
    st.subheader("👀 لمحة من بيانات الوعود المكسورة")
    st.dataframe(df[display_cols].head(15), use_container_width=True, hide_index=True)
    st.subheader("📊 ملخص الوعود المكسورة لكل محصّل")
    if summary.get("summary_df") is not None:
        st.dataframe(summary["summary_df"], use_container_width=True, hide_index=True)
    if net_col and net_col in df.columns:
        st.metric("💰 إجمالي صافي المديونية", f"{pd.to_numeric(df[net_col], errors='coerce').sum():,.2f}")
    st.subheader("📋 جدول الوعود المكسورة التفصيلي")
    st.dataframe(df[display_cols], use_container_width=True, hide_index=True)
    out_excel = io.BytesIO()
    with pd.ExcelWriter(out_excel, engine="openpyxl") as writer:
        df.to_excel(writer, index=False, sheet_name="الوعود المكسورة")
    st.download_button(
        "⬇️ تحميل الوعود المكسورة (Excel)", data=out_excel.getvalue(),
        file_name=f"الوعود_المكسورة_{target_date:%Y-%m-%d}.xlsx",
        mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        use_container_width=True, key="broken_excel_download", type="primary",
    )


