CLASSIFICATION_AGENT_FILTER_KEY = "classification_selected_agent"


def _event_value(item, key, default=None):
    if isinstance(item, dict):
        return item.get(key, default)
    return getattr(item, key, default)


def _extract_selected_agent(event, fig):
    selection = _event_value(event, "selection")
    points = _event_value(selection, "points", []) if selection is not None else []
    if not points:
        return None
    point = points[0]
    selected = _event_value(point, "customdata")
    if isinstance(selected, (list, tuple)):
        selected = selected[0] if selected else None
    if selected is None:
        curve_number = _event_value(point, "curve_number", _event_value(point, "curveNumber", 0))
        point_index = _event_value(point, "point_index", _event_value(point, "pointNumber"))
        if point_index is None or curve_number >= len(fig.data):
            return None
        trace = fig.data[curve_number]
        orientation = getattr(trace, "orientation", None)
        values = trace.y if orientation == "h" else trace.x
        if values is not None and point_index < len(values):
            selected = values[point_index]
    return str(selected).strip() if selected is not None else None


def render_selectable_chart(fig, key):
    """عرض رسم Plotly مع التقاط اختيار محصّل وإعادة تشغيل الصفحة لتطبيق الفلتر."""
    try:
        event = st.plotly_chart(
            fig,
            use_container_width=True,
            config=PLOTLY_CONFIG,
            key=key,
            on_select="rerun",
            selection_mode=("points",),
        )
    except TypeError:
        # توافق مع إصدارات Streamlit القديمة التي لا تدعم on_select.
        st.plotly_chart(fig, use_container_width=True, config=PLOTLY_CONFIG, key=key)
        return
    selected = _extract_selected_agent(event, fig)
    if selected:
        current = st.session_state.get(CLASSIFICATION_AGENT_FILTER_KEY)
        if selected != current:
            st.session_state[CLASSIFICATION_AGENT_FILTER_KEY] = selected
            st.rerun()


def get_classification_view(df, sales_col):
    """تطبيق المحصّل المختار على بيانات التصنيف مع إبقاء العرض كاملًا افتراضيًا."""
    if not sales_col or sales_col not in df.columns:
        return df
    selected = st.session_state.get(CLASSIFICATION_AGENT_FILTER_KEY)
    if not selected:
        return df
    mask = df[sales_col].astype(str).str.strip().eq(str(selected).strip())
    if not mask.any():
        st.session_state.pop(CLASSIFICATION_AGENT_FILTER_KEY, None)
        return df
    return df.loc[mask].copy()


def render_classification_filter_notice(df, sales_col):
    selected = st.session_state.get(CLASSIFICATION_AGENT_FILTER_KEY)
    if not selected:
        return
    c1, c2 = st.columns([4, 1])
    with c1:
        st.info(f"🎯 الفلتر النشط: عرض كل مؤشرات ورسوم المحصّل «{selected}»")
    with c2:
        if st.button("إظهار الكل", key="clear_classification_agent_filter", use_container_width=True):
            st.session_state.pop(CLASSIFICATION_AGENT_FILTER_KEY, None)
            st.rerun()


def chart_card(title: str, render_fn):
    with st.container(border=True):
        st.subheader(title)
        render_fn()



def _compute_agent_perf(df, class_col, sales_col):
    agent_perf = (
        df.groupby(sales_col)[class_col]
        .agg(["count", "sum"])
        .rename(columns={"count": "إجمالي المكالمات", "sum": "ناجحة"})
    )
    agent_perf["غير ناجحة"] = agent_perf["إجمالي المكالمات"] - agent_perf["ناجحة"]
    agent_perf["نسبة النجاح %"] = (agent_perf["ناجحة"] / agent_perf["إجمالي المكالمات"] * 100).round(1)
    return agent_perf.sort_values("نسبة النجاح %", ascending=False).reset_index()


def render_metric_cards(df, class_col, sales_col, time_col):
    has_class = bool(class_col and class_col in df.columns)
    has_wasted = WASTED_TIME_COL in df.columns
    has_sales = bool(sales_col and sales_col in df.columns)
    total = len(df)
    success_count = int((df[class_col] == 1).sum()) if has_class else None
    fail_count = int((df[class_col] == 0).sum()) if has_class else None
    success_rate = round(success_count / total * 100, 1) if has_class and total else 0
    fail_rate = round(fail_count / total * 100, 1) if has_class and total else 0

    with st.container(border=True):
        st.subheader("📌 ملخص الأداء")
        metrics = st.columns(5 if has_wasted else 4)
        metrics[0].metric("📞 إجمالي المكالمات", f"{total:,}")
        metrics[1].metric(
            "✅ المكالمات الناجحة",
            f"{success_count:,}" if success_count is not None else "—",
            f"{success_rate}% من الإجمالي" if has_class else None,
        )
        metrics[2].metric(
            "⛔ المكالمات غير الناجحة",
            f"{fail_count:,}" if fail_count is not None else "—",
            f"{fail_rate}% من الإجمالي" if has_class else None,
        )
        agent_count = int(df[sales_col].nunique()) if has_sales else "—"
        metrics[3].metric("👥 عدد المحصّلين", f"{agent_count:,}" if isinstance(agent_count, int) else agent_count)
        if has_wasted:
            total_wasted = pd.to_numeric(df[WASTED_TIME_COL], errors="coerce").sum()
            avg_wasted = pd.to_numeric(df[WASTED_TIME_COL], errors="coerce").mean()
            metrics[4].metric("⏱️ الوقت المهدر", f"{total_wasted:,.1f} دقيقة", f"متوسط {avg_wasted:.1f} دقيقة")



def render_pie_chart(df, class_col):
    has_class = class_col and class_col in df.columns

    def _pie():
        if not has_class:
            st.info("لا يوجد عمود تصنيف لعرض توزيع النتائج.")
            return
        labels_series = df[class_col].map({1: "ناجحة", 0: "غير ناجحة"})
        pie_df = labels_series.value_counts().reset_index()
        pie_df.columns = ["التصنيف", "العدد"]
        success_rate = round((df[class_col] == 1).mean() * 100, 1) if len(df) else 0
        fig = px.pie(
            pie_df, names="التصنيف", values="العدد", hole=0.62,
            color="التصنيف", color_discrete_map=CHART_COLORS,
        )
        fig.update_traces(
            textinfo="percent",
            textfont_size=13,
            marker=dict(line=dict(color="#0E1420", width=3)),
            hovertemplate="<b>%{label}</b><br>العدد: %{value:,}<br>النسبة: %{percent}<extra></extra>",
        )
        fig.update_layout(
            **PLOTLY_LAYOUT, showlegend=True,
            legend=dict(orientation="h", yanchor="bottom", y=-0.15, x=0.5, xanchor="center"),
            annotations=[dict(text=f"{success_rate}% نجاح",
                               x=0.5, y=0.5, font_size=22, font_color=COLOR_SUCCESS, showarrow=False)],
        )
        st.plotly_chart(fig, use_container_width=True, config=PLOTLY_CONFIG)

    chart_card("🎯 توزيع نتائج التصنيف", _pie)


def render_wasted_bar(df, sales_col, top_n=10):
    has_wasted = WASTED_TIME_COL in df.columns
    has_sales = sales_col and sales_col in df.columns

    def _wasted_bar():
        if not (has_wasted and has_sales):
            st.info("يلزم وجود عمود المحصّل وعمود الوقت المهدر لعرض هذا الرسم.")
            return
        wasted_by_agent = df.groupby(sales_col)[WASTED_TIME_COL].sum().sort_values(ascending=False)
        if top_n:
            wasted_by_agent = wasted_by_agent.head(top_n)
        wasted_by_agent = wasted_by_agent.reset_index()
        chart_height = max(300, 32 * len(wasted_by_agent))
        fig2 = px.bar(
            wasted_by_agent, x=WASTED_TIME_COL, y=sales_col, orientation="h",
            color=WASTED_TIME_COL, color_continuous_scale=[COLOR_ACCENT, COLOR_WARN, COLOR_FAIL],
        )
        fig2.update_layout(
            **PLOTLY_LAYOUT, yaxis={"categoryorder": "total ascending", "title": ""},
            xaxis_title="الوقت المهدر (دقيقة)", coloraxis_showscale=False, height=chart_height,
        )
        fig2.update_traces(
            marker_line_width=0,
            hovertemplate="<b>%{y}</b><br>الوقت المهدر: %{x:,.1f} دقيقة<extra></extra>",
        )
        st.plotly_chart(fig2, use_container_width=True, config=PLOTLY_CONFIG)

    title = f"🏆 أعلى {top_n} محصّلين في الوقت المهدر" if top_n else "🏆 كل المحصّلين حسب الوقت المهدر"
    chart_card(title, _wasted_bar)


def render_agent_perf_chart(df, class_col, sales_col, with_table=True):
    has_class = class_col and class_col in df.columns
    has_sales = sales_col and sales_col in df.columns
    if not (has_class and has_sales):
        return
    agent_perf = _compute_agent_perf(df, class_col, sales_col)

    def _agent_perf():
        fig3 = px.bar(
            agent_perf, x=sales_col, y=["ناجحة", "غير ناجحة"],
            color_discrete_sequence=[COLOR_SUCCESS, COLOR_FAIL], barmode="stack",
        )
        fig3.update_layout(**PLOTLY_LAYOUT, legend_title_text="", xaxis_title="", yaxis_title="عدد المكالمات",
                           legend=dict(orientation="h", yanchor="bottom", y=-0.28, x=0.5, xanchor="center"),
                           height=430)
        fig3.update_traces(
            marker_line_width=0,
            hovertemplate="<b>%{x}</b><br>%{fullData.name}: %{y:,} مكالمة<extra></extra>",
        )
        st.plotly_chart(fig3, use_container_width=True, config=PLOTLY_CONFIG)
        if with_table:
            with st.expander("📋 جدول ترتيب المحصّلين حسب نسبة النجاح"):
                st.dataframe(agent_perf, use_container_width=True)

    chart_card("📊 أداء كل محصّل (ناجحة مقابل غير ناجحة)", _agent_perf)


def render_wasted_hist(df):
    has_wasted = WASTED_TIME_COL in df.columns

    def _hist():
        if not has_wasted:
            st.info("يلزم وجود عمود الوقت المهدر لعرض هذا التوزيع.")
            return
        fig4 = px.histogram(df, x=WASTED_TIME_COL, nbins=20, color_discrete_sequence=[COLOR_ACCENT])
        fig4.update_layout(**PLOTLY_LAYOUT, bargap=0.08, xaxis_title="الوقت المهدر (دقيقة)", yaxis_title="عدد المرات")
        fig4.update_traces(hovertemplate="الوقت المهدر: %{x:.1f} دقيقة<br>عدد المرات: %{y}<extra></extra>")
        st.plotly_chart(fig4, use_container_width=True, config=PLOTLY_CONFIG)

    chart_card("⏱️ توزيع الوقت المهدر بين المكالمات", _hist)


def render_trend_chart(df, class_col, time_col):
    has_class = class_col and class_col in df.columns
    has_time = time_col and time_col in df.columns

    def _trend():
        if not has_time:
            st.info("يلزم وجود عمود التاريخ لعرض اتجاه المكالمات بمرور الوقت.")
            return
        trend_df = df.copy()
        trend_df[time_col] = pd.to_datetime(trend_df[time_col], errors="coerce")
        trend_df["اليوم"] = trend_df[time_col].dt.date
        if has_class:
            trend_df["الحالة"] = trend_df[class_col].map({1: "ناجحة", 0: "غير ناجحة"})
            daily = trend_df.groupby(["اليوم", "الحالة"]).size().reset_index(name="عدد المكالمات")
            fig5 = px.area(daily, x="اليوم", y="عدد المكالمات", color="الحالة", color_discrete_map=CHART_COLORS)
        else:
            daily = trend_df.groupby("اليوم").size().reset_index(name="عدد المكالمات")
            fig5 = px.area(daily, x="اليوم", y="عدد المكالمات", color_discrete_sequence=[COLOR_ACCENT])
        fig5.update_traces(line_width=2, hovertemplate="اليوم: %{x|%Y-%m-%d}<br>عدد المكالمات: %{y}<extra></extra>")
        fig5.update_layout(**PLOTLY_LAYOUT, legend_title_text="", xaxis_title="", yaxis_title="عدد المكالمات",
                           xaxis=dict(tickformat="%Y-%m-%d", nticks=8))
        st.plotly_chart(fig5, use_container_width=True, config=PLOTLY_CONFIG)

    chart_card("📅 اتجاه عدد المكالمات يوميًا", _trend)


def render_quick_summary(df, class_col=None, sales_col=None, time_col=None):
    render_metric_cards(df, class_col, sales_col, time_col)
    render_highlights(df, class_col, sales_col, time_col)
    a, b = st.columns(2)
    with a:
        render_pie_chart(df, class_col)
    with b:
        render_trend_chart(df, class_col, time_col)
    c, d = st.columns(2)
    with c:
        render_agent_perf_chart(df, class_col, sales_col, with_table=False)
    with d:
        render_wasted_bar(df, sales_col)



def render_highlights(df, class_col, sales_col, time_col):
    has_class = bool(class_col and class_col in df.columns)
    has_sales = bool(sales_col and sales_col in df.columns)
    has_wasted = WASTED_TIME_COL in df.columns
    has_time = bool(time_col and time_col in df.columns)
    st.subheader("💡 أهم الملاحظات")
    cols = st.columns(3)
    with cols[0]:
        if has_class and has_sales:
            perf = _compute_agent_perf(df, class_col, sales_col)
            perf = perf[perf["إجمالي المكالمات"] >= 3]
            if len(perf):
                top = perf.iloc[0]
                st.metric("🏅 أفضل محصّل", str(top[sales_col]), f"{top['نسبة النجاح %']}% نجاح")
            else:
                st.info("لا توجد بيانات كافية")
        else:
            st.info("يلزم وجود عمود التصنيف والمحصّل")
    with cols[1]:
        if has_wasted and has_sales:
            totals = df.groupby(sales_col)[WASTED_TIME_COL].sum().sort_values(ascending=False)
            if len(totals):
                st.metric("🐌 الأكثر إهدارًا للوقت", str(totals.index[0]), f"{totals.iloc[0]:.1f} دقيقة")
            else:
                st.info("لا توجد بيانات كافية")
        else:
            st.info("يلزم وجود عمود المحصّل والوقت المهدر")
    with cols[2]:
        if has_time:
            t = pd.to_datetime(df[time_col], errors="coerce")
            if t.notna().any():
                daily = t.dt.date.value_counts()
                st.metric("📅 أكثر يوم نشاطًا", str(daily.index[0]), f"{int(daily.iloc[0])} مكالمة")
            else:
                st.info("لا توجد تواريخ صالحة")
        else:
            st.info("يلزم وجود عمود التاريخ")



def render_comparison_matrix(df, class_col, sales_col):
    """جدول مقارنة شامل لكل المحصّلين + خريطة أداء (نسبة النجاح مقابل الوقت المهدر)."""
    has_class = class_col and class_col in df.columns
    has_sales = sales_col and sales_col in df.columns
    has_wasted = WASTED_TIME_COL in df.columns

    if not (has_class and has_sales):
        st.info("يلزم وجود عمود التصنيف وعمود المحصّل لبناء جدول المقارنة.")
        return

    perf = _compute_agent_perf(df, class_col, sales_col)

    if has_wasted:
        wasted_agg = df.groupby(sales_col)[WASTED_TIME_COL].agg(["sum", "mean"]).round(1)
        wasted_agg.columns = ["إجمالي الوقت المهدر", "متوسط الوقت المهدر"]
        perf = perf.merge(wasted_agg, left_on=sales_col, right_index=True, how="left")

    def _table():
        st.dataframe(
            perf.rename(columns={sales_col: "المحصّل"}),
            use_container_width=True,
            hide_index=True,
        )

    chart_card(f"📋 جدول المقارنة الشامل — كل المحصّلين ({len(perf)})", _table)

    if has_wasted:
        def _scatter():
            fig = px.scatter(
                perf, x="نسبة النجاح %", y="إجمالي الوقت المهدر", size="إجمالي المكالمات",
                hover_name=sales_col, color="نسبة النجاح %",
                color_continuous_scale=[COLOR_FAIL, COLOR_WARN, COLOR_SUCCESS],
            )
            avg_success = perf["نسبة النجاح %"].mean()
            avg_wasted = perf["إجمالي الوقت المهدر"].mean()
            fig.add_vline(x=avg_success, line_dash="dot", line_color=THEME["text_dim"], opacity=0.5)
            fig.add_hline(y=avg_wasted, line_dash="dot", line_color=THEME["text_dim"], opacity=0.5)
            fig.update_traces(hovertemplate=f"%{{text}}<br>نسبة النجاح: %{{x:.1f}}%<br>الوقت المهدر: %{{y:.1f}} دقيقة<extra></extra>",
                              marker=dict(line=dict(color=THEME["chart_marker"], width=1)))
            fig.update_layout(
                **PLOTLY_LAYOUT, coloraxis_showscale=False,
                xaxis_title="نسبة النجاح %", yaxis_title="إجمالي الوقت المهدر (دقيقة)", height=520,
            )
            st.plotly_chart(fig, use_container_width=True, config=PLOTLY_CONFIG)
            st.caption(
                "🔵 حجم الفقاعة = عدد المكالمات · الخطوط المنقّطة = المتوسط العام. "
                "أعلى يمين = أداء ممتاز، أسفل يمين = ممتاز بس وقته بيتهدر، أعلى يسار = نجاح قليل بجهد وقت أقل، أسفل يسار = محتاج متابعة."
            )

        chart_card("🧭 خريطة الأداء: نسبة النجاح مقابل الوقت المهدر", _scatter)


def render_kpi_cards(df, class_col, sales_col, time_col):
    has_class = bool(class_col and class_col in df.columns)
    has_sales = bool(sales_col and sales_col in df.columns)
    has_wasted = WASTED_TIME_COL in df.columns
    total_calls = len(df)
    success_count = int((df[class_col] == 1).sum()) if has_class else None
    fail_count = int((df[class_col] == 0).sum()) if has_class else None
    success_rate = round(success_count / total_calls * 100, 1) if has_class and total_calls else None
    total_wasted = round(df[WASTED_TIME_COL].sum(), 1) if has_wasted else None
    n_agents = int(df[sales_col].nunique()) if has_sales else None
    st.subheader("📌 مؤشرات الأداء الرئيسية")
    row1 = st.columns(4)
    row1[0].metric("📞 إجمالي المكالمات", total_calls)
    row1[1].metric("✅ ناجحة", success_count if has_class else "—", f"{success_rate}%" if has_class else "")
    row1[2].metric("⛔ غير ناجحة", fail_count if has_class else "—")
    row1[3].metric("👥 عدد المحصّلين", n_agents if has_sales else "—")
    row2 = st.columns(4)
    row2[0].metric("🎯 نسبة النجاح", f"{success_rate}%" if has_class else "—")
    if has_sales and has_wasted:
        wasted_sum = df.groupby(sales_col)[WASTED_TIME_COL].sum()
        row2[1].metric("🐌 أعلى إهدار للوقت", str(wasted_sum.idxmax()), f"{wasted_sum.max():.1f} دقيقة")
    else:
        row2[1].metric("🐌 أعلى إهدار للوقت", "—")
    row2[2].metric("⏱️ إجمالي الوقت المهدر", total_wasted if has_wasted else "—")
    row2[3].metric("📊 متوسط الوقت المهدر", f"{df[WASTED_TIME_COL].mean():.1f}" if has_wasted else "—")



def render_full_dashboard(df, class_col=None, sales_col=None, time_col=None):
    render_kpi_cards(df, class_col, sales_col, time_col)
    render_highlights(df, class_col, sales_col, time_col)
    a, b = st.columns(2)
    with a:
        render_pie_chart(df, class_col)
    with b:
        render_trend_chart(df, class_col, time_col)
    render_agent_perf_chart(df, class_col, sales_col, with_table=True)
    c, d = st.columns(2)
    with c:
        render_wasted_bar(df, sales_col, top_n=None)
    with d:
        render_wasted_hist(df)
    render_comparison_matrix(df, class_col, sales_col)



